node - <<'NODE'
const fs=require('fs');
for (const arm of ['without','with']) {
  console.log('='.repeat(20), arm);
  const lines=fs.readFileSync(`evidence/rejection/${arm}/session.jsonl`,'utf8').trim().split('\n');
  for (const line of lines) {
    const e=JSON.parse(line);
    if(e.type==='assistant/message'){
      for(const b of e.data.message.content||[]){
        if(b.type==='reasoning'||b.type==='text') console.log(`[${e.data.turn}/${e.data.step} ${b.type}] ${b.text}`);
      }
    }
  }
}
