args.new_string:
/**
 * PNWF-B/C: the pulse is the first ordinary read of a resumed session. A clean taskless
 * repository with a direct commit is already a reviewable outcome, so it must not expose only
 * CHECKPOINT and "propose the next step". This mirrors `palimpsest_work action=readiness`:
 * before a conclusion, name the DELIVER action; after a current DELIVER, point at that
 * conclusion instead of asking for a duplicate. Dirty, blocked and formal-task states keep
 * their existing guidance.
 *
 * The action is computed BEFORE the formal next action because a session-level CHECKPOINT in
 * that list let a resumed session stop with the commit preserved in Git but no episode record.
 * The next session could then see no delivery at all. When this branch applies, DELIVER/REUSE
 * is the first mechanical action and CHECKPOINT is withheld.
 */
const direct = status.directOutcome;
let directDelivery: "RECORD" | "REUSE" | null = null;
if (
  status.tasks.length === 0 &&
  pendingWork.length === 0 &&
  blocked.length === 0 &&
  verifying.length === 0 &&
  !status.attempts.some((attempt) => ["CREATED", "LEASED", "RUNNING"].includes(attempt.state)) &&
  direct?.relation === "DIRECT_AHEAD" &&
  direct.uncommittedPaths.length === 0
) {
  let latestIndex = -1;
  let latest: ReturnType<typeof parseEpisodeConclusion> = null;
  for (let index = 0; index < entries.length; index += 1) {
    const parsed = parseEpisodeConclusion(entries[index]!.entry.body);
    if (parsed !== null) {
      latest = parsed;
      latestIndex = index;
    }
  }
  const currentDeliver =
    latest?.intent === "DELIVER" &&
    latest.basis.projectRevision === basis.projectRevision &&
    latest.basis.headCommit === basis.headCommit &&
    latestIndex === entries.length - 1;
  directDelivery = currentDeliver ? "REUSE" : "RECORD";
}
const directHead = direct?.repositoryHead ?? "";
const requiredAction =
  directDelivery === "RECORD" && directHead !== ""
    ? Object.freeze({
        kind: "RECORD_DIRECT_DELIVERY" as const,
        action: "palimpsest_work action=conclude intent=DELIVER with your statement and the committed artifact paths",
        reason:
          `the repository has a direct commit at ${directHead.slice(0, 12)}, but the episode has no recorded DELIVER conclusion. ` +
          "A Git commit is not an episode record: the next session sees only the journal. " +
          "If this commit is the deliverable, record it before the session stops; otherwise record the judgement that fits the actual state",
        repositoryHead: directHead,
      })
    : null;

const nextActions: string[] = [];
const verifying = pendingWork.filter((task) => task.state === "VERIFYING");
const ready = pendingWork.filter((task) => task.state === "READY");
const active = pendingWork.filter((task) => task.state === "ACTIVE");
const running = status.attempts.filter((attempt) => attempt.state === "RUNNING");
if (directDelivery === "RECORD") {
  nextActions.push(`agent: ${requiredAction!.action} — ${requiredAction!.reason}`);
} else if (directDelivery === "REUSE") {
  nextActions.push("agent: reply using the recorded conclusion; it already covers this episode");
}
/**
 * R2: the Work owner's pure explanation is the ONE source of the formal next action. The old
 * broad-state inference remains only for a compatibility projection that does not carry it.
 */
if (status.nextAction !== undefined) {
  if (status.nextAction.executable && status.nextAction.action !== null) {
    nextActions.push(`agent: ${status.nextAction.action}`);
  } else {
    nextActions.push(
      `${status.nextAction.kind.startsWith("WAIT_OPERATOR") ? "operator" : "agent"}: ${status.nextAction.detail}`,
    );
  }
  if (status.nextAction.session?.mayEnd === true && directDelivery === null) {
    nextActions.push(
      `session: ${status.nextAction.session.action ?? "record an episode conclusion"} — ${status.nextAction.session.detail}`,
    );
  }
} else {
  if (blocked.length > 0) nextActions.push("operator: recover the pending canonical effect before starting dependent work");
  if (verifying.length > 0) nextActions.push("operator: review the delivered result and accept or reject it");
  if (ready.length > 0) nextActions.push("agent: palimpsest_work action=next (mechanical step is legal)");
  if (active.length > 0 && running.length > 0) nextActions.push("agent: palimpsest_work action=complete when the work is done");
}
if (openQuestions.length > 0) nextActions.push("agent: address an open question by investigation or a proposal; do not treat it as accepted");
if (requiredAction === null && pendingWork.length === 0 && verifying.length === 0 && status.nextAction?.kind !== "NO_FORMAL_WORK") {
  nextActions.push("agent: propose the next bounded step in the project journal");
}
if (nextActions.length === 0) nextActions.push("status is quiescent; read the recent journal before proposing a change");

