args.new_string:
const readPulse = async () => (await call(installed, "palimpsest_continuity", { action: "pulse" })) as unknown as Pulse;
const pulseMechanical = (value: Pulse) => value.nextActions.mechanical.join("\n");
const firstPulseAction = (value: Pulse) => value.nextActions.mechanical[0] ?? "";
const pulseOffersDeliver = (value: Pulse) => /palimpsest_work action=conclude intent=DELIVER/u.test(pulseMechanical(value));
const pulsePointsAtConclusion = (value: Pulse) => /reply using the recorded conclusion/u.test(pulseMechanical(value));

const initial = await read();
expect(initial.action).toBe("CONTINUE_WORK");
expect(offersDeliver(initial)).toBe(false);
const initialPulse = await readPulse();
expect(pulseOffersDeliver(initialPulse)).toBe(false);
expect(initialPulse.requiredAction ?? null).toBeNull();

writeFileSync(join(repo, "docs", "result.md"), "# A real uncommitted draft\n");
const dirty = await read();
expect(dirty.action).toBe("CONTINUE_WORK");
expect(dirty.directOutcome?.uncommittedPaths.length).toBeGreaterThan(0);
expect(offersDeliver(dirty)).toBe(false);
const dirtyPulse = await readPulse();
expect(pulseOffersDeliver(dirtyPulse)).toBe(false);
expect(dirtyPulse.requiredAction ?? null).toBeNull();

execFileSync("git", ["add", "-A"], { cwd: repo });
execFileSync("git", ["-c", "user.email=t@t.t", "-c", "user.name=t", "commit", "-qm", "direct result"], { cwd: repo });
const direct = execFileSync("git", ["rev-parse", "HEAD"], { cwd: repo, encoding: "utf8" }).trim();
expect(direct).not.toBe(head);

const committed = await read();
expect(committed.action).toBe("SEMANTIC_JUDGEMENT");
expect(committed.task).toBeNull();
expect(committed.attempt).toBeNull();
expect(committed.directOutcome).toMatchObject({ repositoryHead: direct, projectHead: head, relation: "DIRECT_AHEAD" });
expect(committed.reasons.join(" ")).toContain(direct);
expect(committed.next.join(" ")).toContain("palimpsest_work action=conclude intent=DELIVER");
const committedPulse = await readPulse();
expect(committedPulse.episode.state).toBe("OPEN");
expect(committedPulse.requiredAction).toMatchObject({
  kind: "RECORD_DIRECT_DELIVERY",
  repositoryHead: direct,
});
expect(committedPulse.requiredAction?.reason).toMatch(/Git commit is not an episode record/iu);
expect(firstPulseAction(committedPulse)).toContain("palimpsest_work action=conclude intent=DELIVER");
expect(pulseMechanical(committedPulse)).not.toContain("intent=CHECKPOINT");
expect(pulseMechanical(committedPulse)).not.toContain("propose the next bounded step");
expect(pulseOffersDeliver(committedPulse)).toBe(true);

const delivered = (await call(installed, "palimpsest_work", {
  action: "conclude",
  intent: "DELIVER",
  statement: "The direct commit is the reviewable result.",
  artifacts: ["docs/result.md"],
})) as unknown as Conclude;
expect(delivered.state).toBe("RECORDED");
expect(delivered.session.mayEnd).toBe(true);

const after = await read();
expect(after.action).toBe("SEMANTIC_JUDGEMENT");
expect(after.next).toEqual(["reply using the recorded conclusion"]);
expect(offersDeliver(after)).toBe(false);
const afterPulse = await readPulse();
expect(afterPulse.episode.state).toBe("DELIVERED");
expect(afterPulse.episode.current).toBe(true);
expect(afterPulse.requiredAction ?? null).toBeNull();
expect(firstPulseAction(afterPulse)).toContain("reply using the recorded conclusion");
expect(pulsePointsAtConclusion(afterPulse)).toBe(true);
expect(pulseOffersDeliver(afterPulse)).toBe(false);
expect(pulseMechanical(afterPulse)).not.toContain("intent=CHECKPOINT");

// A later project fact reopens the conclusion; the pulse must ask for a fresh judgement.
await installed.application.projectWorkspace!.recordJournalEntry({
  kind: "REFERENCE_NOTE",
  title: "Later maintenance observation",
  body: "A new observation arrived after the recorded conclusion.",
  provenance: "regression test",
  relatedRefs: [{ kind: "git_commit", id: direct }],
});
const reopenedPulse = await readPulse();
expect(reopenedPulse.episode.state).toBe("REOPENED");
expect(reopenedPulse.requiredAction?.kind).toBe("RECORD_DIRECT_DELIVERY");
expect(pulseOffersDeliver(reopenedPulse)).toBe(true);
expect(pulsePointsAtConclusion(reopenedPulse)).toBe(false);

// A later uncommitted edit is not hidden by the recorded conclusion.
writeFileSync(join(repo, "docs", "result.md"), "# An uncommitted revision\n");
const dirtyAfter = await read();
expect(dirtyAfter.action).toBe("CONTINUE_WORK");
expect(offersDeliver(dirtyAfter)).toBe(false);
const dirtyAfterPulse = await readPulse();
expect(dirtyAfterPulse.requiredAction ?? null).toBeNull();
expect(pulseOffersDeliver(dirtyAfterPulse)).toBe(false);
expect(pulsePointsAtConclusion(dirtyAfterPulse)).toBe(false);

